  'v3.problem.eyebrow': { en: 'The problem', fr: 'Le problème', es: 'El problema', de: 'Das Problem', zh: '问题所在', ja: '問題' },
  'v3.problem.title': { en: 'Your context window is <em>valuable</em>', fr: 'Votre fenêtre de contexte est <em>précieuse</em>', es: 'Tu ventana de contexto es <em>valiosa</em>', de: 'Dein Kontextfenster ist <em>wertvoll</em>', zh: '你的上下文窗口很宝贵', ja: 'コンテキストウィンドウは貴重です' },
  'v3.problem.lede': { en: "AI agents don't need more output. They need more relevant output.", fr: "Les agents IA n'ont pas besoin de plus de sortie. Ils ont besoin d'une sortie plus pertinente.", es: 'Los agentes de IA no necesitan más salida. Necesitan una salida más relevante.', de: 'KI-Agenten brauchen nicht mehr Output. Sie brauchen relevanteren Output.', zh: 'AI 代理不需要更多输出，而是需要更相关的输出。', ja: 'AI エージェントに必要なのは、出力の量ではなく関連性です。' },
  'v3.problem.chart_sr': { en: 'Chart: a Claude Code context window late in a session: 86% used, close to autocompact. The fixed costs are tiny (system prompt and tools 3%, MCP tools 1%, memory files 1%, skills 0.5%); what fills the window is conversation history at 62% and CLI output and logs at 18%. After RTK filters that output the CLI share drops to 5% and total usage to 73%, back out of compaction territory.', fr: "Graphique : une fenêtre de contexte Claude Code en fin de session : 86 % utilisés, proche de l'autocompactage. Les coûts fixes sont minimes (prompt système et outils 3 %, outils MCP 1 %, fichiers mémoire 1 %, skills 0,5 %) ; ce qui remplit la fenêtre, c'est l'historique de conversation à 62 % et les sorties CLI et logs à 18 %. Une fois filtré par RTK, la part CLI tombe à 5 % et l'usage total à 73 %.", es: 'Gráfico: una ventana de contexto de Claude Code al final de una sesión: 86 % usado, cerca del autocompactado. Los costes fijos son mínimos (prompt del sistema y herramientas 3 %, herramientas MCP 1 %, archivos de memoria 1 %, skills 0,5 %); lo que llena la ventana es el historial de conversación con un 62 % y la salida del CLI y los logs con un 18 %. Tras el filtrado de RTK, la parte del CLI baja al 5 % y el uso total al 73 %.', de: 'Diagramm: ein Claude-Code-Kontextfenster spät in der Session: 86 % belegt, kurz vor dem Autocompact. Die festen Kosten sind winzig (System-Prompt und Tools 3 %, MCP-Tools 1 %, Memory-Dateien 1 %, Skills 0,5 %); gefüllt wird das Fenster vom Gesprächsverlauf mit 62 % und von CLI-Ausgabe und Logs mit 18 %. Nach dem RTK-Filter sinkt der CLI-Anteil auf 5 % und die Gesamtauslastung auf 73 %.', zh: '图表：会话后期的 Claude Code 上下文窗口（）已用 86%，接近自动压缩。固定开销很小（系统提示与工具 3%、MCP 工具 1%、记忆文件 1%、Skills 0.5%）；真正占满窗口的是对话历史 62% 和 CLI 输出与日志 18%。经 RTK 过滤后，CLI 部分降至 5%，总占用降至 73%。', ja: 'グラフ：セッション終盤の Claude Code コンテキストウィンドウ（）使用率 86%、自動コンパクト間近です。固定コストはごくわずか（システムプロンプトとツール 3%、MCP ツール 1%、メモリファイル 1%、スキル 0.5%）で、実際に埋めているのは会話履歴 62% と CLI 出力・ログ 18%。RTK がフィルタリングすると CLI は 5%、全体は 73% まで下がります。' },
  'v3.problem.ctx_head': { en: 'AI context', fr: 'Contexte IA', es: 'Contexto de IA', de: 'KI-Kontext', zh: 'AI 上下文', ja: 'AI コンテキスト' },
