  'v3.proof.d1': { en: 'After a few weeks of daily use: <strong>15,720 commands processed, 130M tokens saved</strong>.', fr: "Après quelques semaines d'usage quotidien : <strong>15 720 commandes traitées, 130 M de tokens économisés</strong>.", es: 'Tras unas semanas de uso diario: <strong>15.720 comandos procesados, 130 M de tokens ahorrados</strong>.', de: 'Nach einigen Wochen täglicher Nutzung: <strong>15.720 Befehle verarbeitet, 130 Mio. Tokens gespart</strong>.', zh: '日常使用几周后：<strong>处理 15,720 条命令，节省 1.30 亿 token</strong>。', ja: '数週間の日常利用で：<strong>15,720 コマンドを処理し、1.30 億トークンを節約</strong>。' },
  'v3.proof.discord': { en: 'See what other developers save in <code>#show-your-gains</code> on Discord', fr: 'Voyez ce que les autres développeurs économisent dans <code>#show-your-gains</code> sur Discord', es: 'Mira lo que ahorran otros desarrolladores en <code>#show-your-gains</code> en Discord', de: 'Sieh in <code>#show-your-gains</code> auf Discord, was andere Entwickler sparen', zh: '在 Discord 的 <code>#show-your-gains</code> 频道查看其他开发者的节省数据', ja: 'Discord の <code>#show-your-gains</code> で他の開発者の節約量を見る' },
